-- Changelog-item: aandachtspunten melden vanuit een formulier.

insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-07-17','nieuw','Oplevering','Bewoners en collega''s kunnen aandachtspunten melden',
   'In een formulier kun je nu de vraag "Aandachtspunt(en)" opnemen. Wie het formulier invult — een bewoner via de feedbacklink of een collega bij de oplevering — meldt daar wat er nog niet in orde is, met foto''s erbij. Die meldingen komen bovenaan in de Oplevering-tab van het dossier te staan. De projectleider zet ze met één klik op de opleverlijst, of wijst ze af met een reden.');
